UPDATE vm_ar_button_info
button_name = #{buttonName}, enable_status = #{enableStatus}, update_time = now(), turn_time = now(), creator = #{creator}, modifier = #{modifier}, delete_flag = #{deleteFlag}, tenant_id = #{tenantId}, industry_code = #{industryCode}, app_ver_code = #{appVerCode}, accept_node = #{acceptNode}, device_range = #{deviceRange},
WHERE id = #{id}

