SELECT COUNT(*) FROM vm_ar_button_info
WHERE delete_flag = 0
AND button_name = #{buttonName}
AND industry_code = #{industryCode}
AND tenant_id = #{tenantId}
AND app_ver_code = #{appVerCode}
AND accept_node = #{acceptNode}
AND enable_status = #{enableStatus}
AND device_range = #{deviceRange}
AND id != #{id}

SELECT id, button_name, enable_status, DATE_FORMAT(create_time, '%Y-%m-%d %H:%i:%s') AS "createTime", DATE_FORMAT(update_time, '%Y-%m-%d %H:%i:%s') AS "updateTime", DATE_FORMAT(turn_time, '%Y-%m-%d %H:%i:%s') AS "turnTime", creator, modifier, delete_flag, tenant_id, industry_code, app_ver_code, accept_node, device_range FROM vm_ar_button_info
AND button_name LIKE CONCAT('%', #{buttonName}, '%')
AND enable_status = #{enableStatus}
AND creator LIKE CONCAT('%', #{creator}, '%')
AND modifier LIKE CONCAT('%', #{modifier}, '%')
AND create_time >= #{createTimeStart}
AND create_time <= #{createTimeEnd}
AND update_time >= #{updateTimeStart}
AND update_time <= #{updateTimeEnd}
AND tenant_id = #{tenantId}
AND accept_node = #{acceptNode}
AND industry_code = #{industryCode}
AND device_range = #{deviceRange}
AND id
#{item}
AND delete_flag = 0
ORDER BY create_time DESC
ORDER BY create_time ASC
ORDER BY create_time DESC
ORDER BY update_time ASC
ORDER BY update_time DESC
ORDER BY turn_time ASC
ORDER BY turn_time DESC
